input.command:
cd css && sed -i 's/^  --color-success-tint: #e8f6ee;/&\n  --color-success-dark: #146c2e;/' tokens.css && python3 - <<'E'
p='pages.css'
s=open(p).read()
s=s.replace(""".plan-ribbon {""",""".plan-featured .btn-primary {
  background: var(--color-success);
  color: #ffffff;
}

.plan-featured .btn-primary:hover {
  background: var(--color-success-dark);
}

.plan-ribbon {""",1)
open(p,'w').write(s)
E
cd ../.. && npx playwright test tests/visual.spec.ts 2>&1 | tail -15

